# Grammar cues. Extension sentences are learning exercises rather than source dialogue.
RULES=[
 dict(id='past-simple',type='一般过去时',pattern='主语 + 动词过去式 + 其他',desc='讲述过去发生并结束的动作，是故事叙述中最常用的时态。',rx=r'\b(?:was|were|said|asked|went|came|saw|looked|turned|ran|walked|jumped|fell|found|took|made|told|heard|thought|gave|left|stood|sat|opened|closed|pulled|pushed|shouted|cried|smiled|laughed|flew|arrived|returned|began|started|stopped|tried|knew|held|brought|caught|threw|struck|fought|won|lost|became|ate|drank|slept|woke|rode|rose|wore|broke|chose)\b',ex=['The monkey opened the door.','The travelers crossed the river.','The demon ran into the cave.','Wukong looked at the sky.','The monk asked a question.','Bajie found some food.','They climbed the mountain.','The king gave them a map.','Everyone heard a loud noise.','The group continued its journey.']),
 dict(id='past-cont',type='过去进行时',pattern='主语 + was/were + 动词 ing',desc='表示过去某一时刻正在进行的动作，常用来交代另一个动作发生时的背景。',rx=r'\b(?:was|were)\s+\w+ing\b',ex=['Wukong was flying through the clouds.','The monk was reading a scripture.','Bajie was looking for food.','Wujing was carrying the luggage.','The demons were waiting outside.','They were walking toward the village.','The king was sitting in the hall.','The children were playing by the river.','It was raining on the mountain.','Everyone was watching the fight.']),
 dict(id='past-perfect',type='过去完成时',pattern='主语 + had + 过去分词',desc='表示在另一个过去动作或时间之前已经完成的动作。',rx=r'\bhad\s+(?:been|gone|come|seen|done|made|found|left|heard|told|taken|given|lost|won|built|brought|caught|thought|stood|sat|held|read|said|got|\w+ed)\b',ex=['The travelers had left before sunrise.','Wukong had seen the demon before.','The monk had finished his meal.','Bajie had found the hidden door.','They had reached the village by noon.','The king had heard the news already.','She had hidden the key in the box.','We had visited the temple once before.','He had learned the spell from his teacher.','The rain had stopped before morning.']),
 dict(id='present-simple',type='一般现在时',pattern='主语 + 动词原形/第三人称单数',desc='表示事实、习惯、状态或经常发生的动作。第三人称单数通常在动词后加 s 或 es。',rx=r'\b(?:I|you|we|they)\s+(?:am|are|have|know|think|want|need|like|love|see|hear|feel|believe)|\b(?:he|she|it|Wukong|Monkey|Bajie|the monk|the demon)\s+(?:is|has|knows|thinks|wants|needs|likes|loves|sees|hears|feels|believes)\b',ex=['Wukong knows many magic spells.','The monk wants to reach the West.','Bajie likes good food.','Wujing carries the luggage.','They travel together.','I know the answer.','We need more water.','The king lives in the palace.','This road leads to the mountain.','The river flows through the valley.']),
 dict(id='present-cont',type='现在进行时',pattern='主语 + am/is/are + 动词 ing',desc='表示现在或当前一段时间正在发生的动作。',rx=r'\b(?:am|is|are)\s+\w+ing\b',ex=['Wukong is looking for the demon.','The monk is resting under a tree.','Bajie is eating a peach.','Wujing is carrying the bags.','They are crossing the bridge.','I am waiting for you.','We are following the river.','The king is speaking to his guards.','The demons are hiding in the cave.','It is getting dark.']),
 dict(id='present-perfect',type='现在完成时',pattern='主语 + have/has + 过去分词',desc='表示过去发生但与现在有关的动作或结果。',rx=r'\b(?:have|has)\s+(?:been|gone|come|seen|done|made|found|left|heard|told|taken|given|lost|won|built|brought|caught|thought|stood|sat|held|read|said|got|\w+ed)\b',ex=['Wukong has found the cave.','The monk has finished his meal.','Bajie has lost his rake.','They have reached the village.','I have seen this demon before.','We have crossed the river.','The king has opened the gate.','She has hidden the treasure.','The guards have caught the thief.','The rain has stopped.']),
 dict(id='present-perfect-cont',type='现在完成进行时',pattern='主语 + have/has been + 动词 ing',desc='强调动作从过去开始并持续到现在，或说明眼前结果的原因。',rx=r'\b(?:have|has)\s+been\s+\w+ing\b',ex=['They have been walking all day.','Wukong has been searching for the demon.','The monk has been waiting by the road.','Bajie has been sleeping under the tree.','We have been following this path.','I have been reading the scripture.','The guards have been watching the gate.','It has been raining since morning.','She has been preparing the meal.','The villagers have been hiding in their homes.']),
 dict(id='future-will',type='一般将来时',pattern='主语 + will + 动词原形',desc='表示将来的动作、临时决定、承诺或预测。',rx=r"\bwill\s+(?!be\s+\w+ed)\w+\b|\b(?:I'll|we'll|you'll|he'll|she'll|they'll)\b",ex=['Wukong will protect the monk.','They will leave tomorrow.','I will show you the way.','We will cross the river together.','The king will send more guards.','Bajie will carry the food.','The demon will return at night.','She will open the gate.','It will rain soon.','You will understand one day.']),
 dict(id='passive',type='被动语态',pattern='主语 + be + 过去分词',desc='强调动作的承受者；be 动词随时态和主语变化，后接过去分词。',rx=r'\b(?:am|is|are|was|were|be|been)\s+(?:tied|trapped|caught|covered|filled|made|called|named|sent|taken|given|told|asked|ordered|invited|locked|hidden|surrounded|defeated|saved|opened|closed|\w+ed)\b',ex=['The monk was captured by the demon.','The door was locked from inside.','The cave was filled with smoke.','The treasure was hidden under the floor.','The guards were sent to the gate.','The travelers were invited into the palace.','The bridge was destroyed by the flood.','The demon was defeated by Wukong.','The message was delivered at noon.','The village was surrounded by mountains.']),
 dict(id='can',type='情态动词 can',pattern='主语 + can/cannot + 动词原形',desc='表示能力、许可或可能性；can 后接动词原形。',rx=r"\bcan(?:not|'t)?\s+\w+\b",ex=['Wukong can fly through the clouds.','Can you open the door?','Bajie can carry the box.','We can rest here.','They cannot cross the river.','The monk can read the scripture.','Can I ask a question?','You can follow this path.','The demon cannot escape.','Everyone can help.']),
 dict(id='could',type='情态动词 could',pattern='主语 + could/couldn’t + 动词原形',desc='可表示过去的能力、可能性或较委婉的请求和建议。',rx=r"\bcould(?:\s+not|n't)?\s+\w+\b",ex=['Wukong could see the palace below.','They could hear a strange sound.','The monk could not find the path.','Could you show me the way?','We could wait until morning.','Bajie could carry the luggage.','The demon could change its shape.','She could swim across the river.','Could they come back safely?','You could try another plan.']),
 dict(id='must',type='情态动词 must',pattern='主语 + must/mustn’t + 动词原形',desc='表示必须、强烈推断或禁止，后接动词原形。',rx=r"\bmust(?:\s+not|n't)?\s+\w+\b",ex=['We must leave before dark.','You must tell the truth.','The travelers must cross the mountain.','Wukong must protect his master.','Bajie must carry the bags.','They must not enter the cave.','The guards must watch the gate.','I must find another way.','The monk must remain calm.','Everyone must work together.']),
 dict(id='should',type='情态动词 should',pattern='主语 + should/shouldn’t + 动词原形',desc='表示建议、责任或较弱的推断。',rx=r"\bshould(?:\s+not|n't)?\s+\w+\b",ex=['We should follow the river.','You should be careful.','Wukong should ask for help.','The monk should rest for a while.','Bajie should not eat so much.','They should leave before sunset.','The guards should close the gate.','I should try a different plan.','She should tell the king.','Everyone should stay together.']),
 dict(id='have-to',type='必须做某事',pattern='主语 + have/has/had to + 动词原形',desc='表示因规则或客观情况而“不得不、必须”做某事。',rx=r'\b(?:have|has|had)\s+to\s+\w+\b',ex=['We have to cross the river.','Wukong has to protect the monk.','Bajie had to carry the luggage.','They have to leave now.','I have to find the key.','The guards have to watch the gate.','She has to tell the truth.','The king had to make a decision.','You have to wait here.','Everyone has to follow the rules.']),
 dict(id='want-to',type='表达意愿',pattern='主语 + want/wants/wanted to + 动词原形',desc='表示想要做某事。第三人称单数现在时使用 wants。',rx=r'\bwant(?:s|ed)?\s+to\s+\w+\b',ex=['I want to see the palace.','Wukong wants to find the demon.','The monk wants to continue the journey.','Bajie wants to eat some fruit.','They want to cross the bridge.','We want to help the villagers.','She wants to speak to the king.','The guards wanted to catch the thief.','He wants to learn magic.','Everyone wants to go home.']),
 dict(id='going-to',type='be going to 计划',pattern='主语 + be going to + 动词原形',desc='表示已经计划、打算做某事，也可根据迹象预测即将发生的事。',rx=r'\b(?:am|is|are|was|were)\s+(?:not\s+)?going\s+to\s+\w+\b',ex=['Wukong is going to enter the cave.','They are going to leave tomorrow.','I am going to ask the king.','Bajie is going to cook dinner.','We are going to cross the river.','The guards are going to open the gate.','It is going to rain.','She is going to tell the truth.','The demon is going to attack.','You are going to hear an amazing story.']),
 dict(id='try-to',type='尝试做某事',pattern='try/tries/tried to + 动词原形',desc='表示努力或尝试做某事。',rx=r'\btr(?:y|ies|ied)\s+to\s+\w+\b',ex=['Wukong tried to open the door.','They tried to cross the river.','Bajie tries to lift the rock.','I will try to help you.','The demon tried to escape.','She tried to warn the guards.','We tried to find another path.','The monk tried to remain calm.','He tried to remember the spell.','Everyone tried to push the cart.']),
 dict(id='let-us',type='提出建议 Let’s',pattern='Let’s + 动词原形',desc='Let’s 是 Let us 的缩写，用于邀请别人一起做某事或提出共同建议。',rx=r"\blet['’]?s\s+\w+\b",ex=["Let's follow the river.","Let's climb the mountain.","Let's ask Wukong.","Let's wait for the others.","Let's find a safe place.","Let's go back to the village.","Let's help the monk.","Let's look inside the cave.","Let's take a short rest.","Let's try another way."]),
 dict(id='imperative',type='祈使句',pattern='动词原形 + 其他',desc='省略主语 you，以动词原形开头，用于命令、请求、提醒或建议。',rx=r"^(?:Look|Listen|Come|Go|Stop|Wait|Find|Tell|Give|Take|Bring|Open|Close|Help|Follow|Hold|Stay|Run|Get|Put|Keep|Be|Watch|Remember|Leave|Show)\b",ex=['Look at the sky.','Wait by the gate.','Follow the path.','Tell me the truth.','Bring the map with you.','Stand back from the river.','Listen to the monk.','Open the wooden box.','Come back before dark.','Be careful on the bridge.']),
 dict(id='there-be',type='There be 句型',pattern='There + be + 名词 + 地点',desc='表示某处存在某人或某物，be 动词根据时态和名词单复数变化。',rx=r"\bthere(?:'s| is| are| was| were| had been| has been| have been)\b",ex=['There is a temple on the hill.','There are two guards at the gate.','There was a boat near the river.','There were many people in the hall.','There has been a strange noise.','There had been a bridge here.','There is some food in the bag.','There are clouds above the mountain.','There was no light in the cave.','There will be a meeting tomorrow.']),
 dict(id='relative',type='定语从句',pattern='名词 + who/that/which + 从句',desc='用 who、that 或 which 补充说明前面的名词。who 常指人，which 常指物。',rx=r'\b(?:who|which|that)\s+(?:is|was|were|had|has|can|could|will|would|\w+ed|\w+s)\b',ex=['The monkey who jumped first was brave.','The road that leads west is very long.','The temple which stood on the hill was old.','The guard who saw the demon shouted.','The key that opens the door is missing.','The fruit which grew on the tree was sweet.','The man who helped them was a farmer.','The cave that they found was dark.','The river which crossed the valley was wide.','The voice that called out belonged to Wukong.']),
 dict(id='if',type='条件状语从句',pattern='If + 条件, 主句',desc='if 引导条件，说明在某种条件下会出现的结果。',rx=r'\bif\b',ex=['If it rains, we will stay here.','If you see the demon, call Wukong.','If they cross the river, they will reach the village.','If Bajie is hungry, he will look for food.','If the gate is open, we can go inside.','If you tell the truth, the king will help you.','If the road is blocked, we must find another way.','If the monk agrees, we will leave tomorrow.','If the guards come, the demon will run away.','If you are tired, take a rest.']),
 dict(id='when',type='时间状语从句 when',pattern='When + 从句, 主句',desc='when 引导时间状语从句，说明主句动作发生的时间。',rx=r'\bwhen\b',ex=['When the sun rose, they continued the journey.','When Wukong returned, everyone was relieved.','When the gate opened, the guards stepped back.','When it stopped raining, they crossed the river.','When the monk spoke, everyone listened.','When night came, they found a place to rest.','When Bajie saw the food, he smiled.','When the demon appeared, Wukong raised his staff.','When they reached the village, the people welcomed them.','When the story ended, the children cheered.']),
 dict(id='while',type='时间状语从句 while',pattern='While + 进行中的动作, 主句',desc='while 表示“当……时”，常连接两个同时进行的动作。',rx=r'\bwhile\b',ex=['While the monk was resting, Wukong watched the road.','While they were walking, it began to rain.','Bajie ate while the others talked.','While the guards were sleeping, the demon escaped.','Wujing waited while Wukong explored the cave.','While the king was speaking, everyone listened.','The birds sang while the sun was rising.','While we are here, we should help the villagers.','She found the key while she was cleaning.','While the river was rising, they built a raft.']),
 dict(id='because',type='原因状语从句',pattern='主句 + because + 原因',desc='because 引导原因，回答“为什么”。',rx=r'\bbecause\b',ex=['They stopped because the road was blocked.','Wukong smiled because he had a plan.','Bajie was tired because he had walked all day.','The villagers hid because the demon was nearby.','We waited because it was raining.','The king was pleased because the travelers helped him.','She shouted because she saw a snake.','The gate was closed because it was late.','He returned because he forgot the map.','Everyone cheered because the demon was defeated.']),
 dict(id='so-result',type='因果结果表达',pattern='原因, so + 结果',desc='so 表示“所以”，连接前面的原因和后面的结果。',rx=r'\bso\b',ex=['It was dark, so they stopped for the night.','The river was deep, so Wukong built a bridge.','Bajie was hungry, so he looked for food.','The gate was locked, so they waited outside.','The demon was strong, so Wukong used magic.','It began to rain, so they entered the cave.','The monk was tired, so they took a rest.','The guards heard a noise, so they ran to the gate.','The road was blocked, so they chose another path.','The villagers were safe, so everyone relaxed.']),
 dict(id='why-dont',type='Why don’t 提建议',pattern='Why don’t we/you + 动词原形?',desc='以疑问形式提出建议，意思是“为什么不……呢”。',rx=r"why\s+don['’]?t\s+(?:we|you)\s+\w+",ex=["Why don't we follow the river?","Why don't we ask Wukong?","Why don't you wait here?","Why don't we look inside the cave?","Why don't we take a rest?","Why don't you tell the king?","Why don't we cross the bridge?","Why don't we call the others?","Why don't you bring some food?","Why don't we try another way?"]),
 dict(id='embedded-q',type='嵌入式疑问句',pattern='主句 + 疑问词 + 陈述语序',desc='疑问词从句放在 know、wonder、ask、find out 等词后面时使用陈述语序。',rx=r'\b(?:know|wonder|ask(?:ed)?|find out|tell me)\b.*\b(?:what|where|why|who|when|how)\b',ex=['Do you know where the road ends?','I wonder what is inside the box.','Can you tell me who called out?','We need to find out why the gate is closed.','She knows where the key is.','He asked when Wukong would return.','I do not know how they crossed the river.','They wondered who would lead the group.','Please tell me what happened here.','The king asked where the demon lived.']),
 dict(id='enough-to',type='形容词 + enough + to do',pattern='be + 形容词 + enough + to + 动词原形',desc='表示“足够……可以做某事”；enough 放在形容词后面。',rx=r'\b\w+\s+enough\s+to\s+\w+\b',ex=['Wukong is strong enough to lift the rock.','The rope is long enough to reach the ground.','She is brave enough to enter the cave.','The water is shallow enough to cross.','Bajie is tall enough to reach the branch.','The room is large enough to hold everyone.','He is old enough to travel alone.','The light is bright enough to guide us.','They are careful enough to climb safely.','Are you ready enough to begin?']),
 dict(id='too-to',type='too + 形容词 + to do',pattern='be + too + 形容词 + to + 动词原形',desc='表示“太……而不能做某事”。',rx=r'\btoo\s+\w+\s+to\s+\w+\b',ex=['The box is too heavy to carry.','The river is too deep to cross.','Bajie is too tired to walk.','The cave is too dark to enter.','The wall is too high to climb.','The road is too narrow to ride on.','It is too late to leave.','The demon is too fast to catch.','The water is too cold to swim in.','The noise is too loud to ignore.']),
 dict(id='comparative',type='比较级',pattern='比较级 + than / 比较级 and 比较级',desc='比较两者差异，或表达程度不断变化。',rx=r'\b(?:better|worse|more|less|bigger|smaller|higher|lower|faster|slower|stronger|weaker|older|younger|longer|shorter|closer|farther|harder|easier)(?:\s+and\s+\w+er|\s+than)\b',ex=['Wukong is stronger than the demon.','This road is shorter than the other one.','The river is wider than before.','Bajie is hungrier than Wujing.','The mountain is higher than the hill.','The cave became darker and darker.','They walked faster and faster.','The sound grew louder and louder.','This plan is better than the first one.','The journey became more and more difficult.']),
 dict(id='as-as',type='同级比较',pattern='as + 形容词/副词 + as',desc='表示两者在某方面程度相同；否定形式表示“不如……”。',rx=r'\bas\s+\w+\s+as\b',ex=['Wukong is as quick as the wind.','The cave is as dark as night.','Bajie is not as careful as Wujing.','The river is as wide as the road.','This box is as heavy as that one.','The demon ran as fast as a horse.','The palace is as beautiful as a dream.','Today is as hot as yesterday.','The second path is not as long as the first.','She spoke as calmly as the monk.']),
 dict(id='whoever',type='Whoever 主语从句',pattern='Whoever + 从句 + 谓语',desc='whoever 表示“无论谁、任何……的人”，整个从句可在句中作主语。',rx=r'\bwhoever\b',ex=['Whoever finds the key can open the door.','Whoever reaches the top first will win.','Whoever tells the truth will be forgiven.','Whoever helps the monk will receive thanks.','Whoever crosses the river must be careful.','Whoever sees Wukong should call me.','Whoever solves the problem can lead the team.','Whoever enters the cave must carry a light.','Whoever finishes early may rest.','Whoever brings the map will show us the way.']),
]

